// Simple Orbit Escape game
// Canvas element with id="game" must exist in the HTML.
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const w = (canvas.width = canvas.clientWidth);
  const h = (canvas.height = canvas.clientHeight);

  const center = { x: w / 2, y: h / 2 };
  const planet = { r: 30 };
  const ship = {
    angle: 0,
    radius: 120,
    innerRadius: 80,
    outerRadius: 140,
    size: 8,
    speed: 0.02,
  };
  const asteroids = [];
  let lastSpawn = 0;
  const spawnInterval = 1500; // ms
  let gameOver = false;

  function spawnAsteroid() {
    // Choose random edge
    const side = Math.floor(Math.random() * 4);
    let x, y, vx, vy;
    const speed = 1.2 + Math.random() * 0.5;
    if (side === 0) {
      // top
      x = Math.random() * w;
      y = -10;
    } else if (side === 1) {
      // right
      x = w + 10;
      y = Math.random() * h;
    } else if (side === 2) {
      // bottom
      x = Math.random() * w;
      y = h + 10;
    } else {
      // left
      x = -10;
      y = Math.random() * h;
    }
    // Vector towards center
    const dx = center.x - x;
    const dy = center.y - y;
    const len = Math.hypot(dx, dy);
    vx = (dx / len) * speed;
    vy = (dy / len) * speed;
    asteroids.push({ x, y, vx, vy, r: 6 });
  }

  function update(dt) {
    if (gameOver) return;
    // Ship orbit
    ship.angle += ship.speed * dt;
    // Toggle radius on input handled elsewhere
    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x += a.vx * dt;
      a.y += a.vy * dt;
      // Remove if near center
      if (Math.hypot(a.x - center.x, a.y - center.y) < planet.r) {
        gameOver = true;
        return;
      }
      // Collision with ship
      const shipPos = {
        x: center.x + Math.cos(ship.angle) * ship.radius,
        y: center.y + Math.sin(ship.angle) * ship.radius,
      };
      if (Math.hypot(a.x - shipPos.x, a.y - shipPos.y) < a.r + ship.size) {
        gameOver = true;
        return;
      }
    }
    // Spawn new asteroid
    if (performance.now() - lastSpawn > spawnInterval) {
      spawnAsteroid();
      lastSpawn = performance.now();
    }
  }

  function draw() {
    ctx.clearRect(0, 0, w, h);
    // Planet
    ctx.fillStyle = '#2b3b4b';
    ctx.beginPath();
    ctx.arc(center.x, center.y, planet.r, 0, Math.PI * 2);
    ctx.fill();
    // Ship
    const shipPos = {
      x: center.x + Math.cos(ship.angle) * ship.radius,
      y: center.y + Math.sin(ship.angle) * ship.radius,
    };
    ctx.fillStyle = '#ffcc00';
    ctx.beginPath();
    ctx.arc(shipPos.x, shipPos.y, ship.size, 0, Math.PI * 2);
    ctx.fill();
    // Asteroids
    ctx.fillStyle = '#888';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    });
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, w, h);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', w / 2, h / 2);
    }
  }

  let lastTime = performance.now();
  function loop() {
    const now = performance.now();
    const dt = (now - lastTime) / 16; // normalize to ~60fps steps
    lastTime = now;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  // Input: space or click toggles between inner and outer orbit radius
  function toggleRadius() {
    ship.radius = ship.radius === ship.innerRadius ? ship.outerRadius : ship.innerRadius;
  }
  window.addEventListener('keydown', e => {
    if (e.code === 'Space') toggleRadius();
  });
  canvas.addEventListener('click', toggleRadius);

  // Start
  requestAnimationFrame(loop);
})();
